ee:variables.ee:set-variable:
%dw 2.0
output application/json
var sId = "SAGA-" ++ now() as String {format: 'yyyy'} ++ '-' ++ upper(uuid()[0 to 6])
---
{
    sagaId: sId,
    s1: sId ++ "-STEP-1",
    s2: sId ++ "-STEP-2",
    s3: sId ++ "-STEP-3"
}

amqp:message.amqp:body:
#[write({
                            sagaId: vars.sagaInit.sagaId,
                            stepId: vars.sagaInit.s1,
                            orderId: vars.tx.orderId,
                            items: vars.tx.rawPayload.items
                        }, "application/json")]

db:update.db:sql:
UPDATE saga_steps 
SET step_state = 'COMPLETED', reply_received_at = CURRENT_TIMESTAMP, result_payload = :res 
WHERE step_id = :stepId;

UPDATE saga_instances 
SET current_step = 2, state_version = state_version + 1 
WHERE saga_id = :sagaId;

UPDATE saga_steps 
SET step_state = 'COMPLETED', reply_received_at = CURRENT_TIMESTAMP, result_payload = :res 
WHERE step_id = :stepId;

UPDATE saga_instances 
SET current_step = 3, state_version = state_version + 1 
WHERE saga_id = :sagaId;

amqp:message.amqp:body:
#[write({
                            sagaId: vars.replyTx.sagaId,
                            stepId: vars.replyTx.sagaId ++ '-STEP-1',
                            reservationId: vars.resPayload.reservationId,
                            reason: "PAYMENT_DECLINED"
                        }, "application/json")]

db:update.db:sql:
UPDATE saga_steps 
SET step_state = 'COMPLETED', reply_received_at = CURRENT_TIMESTAMP, result_payload = :res 
WHERE step_id = :stepId;

UPDATE saga_instances 
SET saga_state = 'COMPLETED', completed_at = CURRENT_TIMESTAMP, state_version = state_version + 1 
WHERE saga_id = :sagaId;

amqp:message.amqp:body:
#[write({
                            sagaId: vars.replyTx.sagaId,
                            stepId: vars.replyTx.sagaId ++ '-STEP-2',
                            paymentId: vars.payPayload.paymentId,
                            reason: "SHIPPING_FAILED"
                        }, "application/json")]

#[write({
                            sagaId: vars.replyTx.sagaId,
                            stepId: vars.replyTx.sagaId ++ '-STEP-1',
                            reservationId: vars.resPayload.reservationId,
                            reason: "SHIPPING_FAILED"
                        }, "application/json")]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    errorCode: "SAGA_NOT_FOUND",
    errorMessage: "No saga found for id: " ++ vars.queryTx.sagaId,
    correlationId: vars.queryTx.correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
}
